import numpy as np
from scipy.optimize import differential_evolution
from itertools import product
# two equal parts, arbitrary two-class symmetric 3-block kernels; exact 0/1 edges allowed.
def opt(a,types):
 def calc(z,full=False):
  x=np.array([(1-z[0])/2,(1-z[0])/2,z[0]]);i=1
  v=[]
  for t in types:
   if t==2:v.append(z[i]);i+=1
   else:v.append(t)
  d,e,p,q=v;P=np.array([[d,p,q],[p,d,q],[q,q,e]])
  R=(P*x)@P;Q=1-P;B=(Q*x)@Q
  av=max(R[P>0],default=0);bv=max(B[P<1],default=0);val=max(av/a,bv)
  return (1/val,x,P,av/bv if bv else 0) if full else val
 r=differential_evolution(calc,[(.000001,.999999)]*(1+types.count(2)),tol=1e-8,popsize=12,maxiter=450,seed=17)
 return calc(r.x,True)
for a in [.17,.19,.2,.21,.24]:
 best=(0,None)
 for types in product([0,1,2],repeat=4):
  c,x,P,ratio=opt(a,types)
  if c>best[0]:best=(c,(types,x,P,ratio))
 print(a,best,flush=True)
